/**
 * Brings an existing workspace up to what a booking service needs.
 *
 * Deployments seeded before the booking flow existed have a tools collection
 * without `reschedule_appointment` and friends, which would leave a confirmation
 * campaign able to ask but not to act. This is idempotent and safe to call on
 * every boot: it adds what is missing and touches nothing else.
 */
export async function upgradeBookingTools(orgId: string) {
  const wanted = TOOLS.filter((t) => /book_appointment|reschedule_appointment|cancel_appointment|send_confirmation|check_availability|draft_note|payment_status|create_payment_link|practice_report|capture_field_enquiry|schedule_approved_visit/.test(t.name));
  const existing = list<Doc & { name?: string }>('tools', (t) => (t as { orgId?: string }).orgId === orgId);
  const missing = wanted.filter((w) => !existing.some((e) => e.name === w.name));
  if (missing.length) {
    insertMany<Doc>(
      'tools',
      missing.map((t) => ({
        id: `tool_${newId('').slice(1, 9)}`,
        orgId,
        name: t.name,
        description: t.description,
        method: t.method,
        endpoint: t.endpoint,
        createdAt: nowIso(),
      })) as Doc[]
    );
  }

  // The appointment assistant is the one campaigns dial with; make sure it can
  // actually do the job it is being asked to do.
  // `draft_note` joins the list at P5: the agent writes down what happened and a
  // person signs it. An existing workspace gets it the same way it got the
  // reschedule tool — idempotently, on boot.
  const profile = businessProfileFor(orgId);
  const NEEDED = [
    'reschedule_appointment',
    'cancel_appointment',
    'lookup_order',
    'send_confirmation',
    'draft_note',
    'payment_status',
    'create_payment_link',
    'practice_report',
    ...(profile.configured && profile.modules.includes('field_service') ? ['capture_field_enquiry', 'schedule_approved_visit'] : []),
  ];
  let repaired = 0;
  for (const assistant of list<Doc & { tools?: string[]; name?: string }>('assistants', (a) => (a as { orgId?: string }).orgId === orgId)) {
    const name = String(assistant.name ?? '').toLowerCase();
    const tools = assistant.tools ?? [];
    const isBookingAgent = /appointment|booking|schedul/.test(name) || tools.includes('book_appointment');
    if (!isBookingAgent) continue;
    const add = NEEDED.filter((t) => !tools.includes(t));
    if (!add.length) continue;
    update('assistants', String(assistant.id), { tools: [...tools, ...add], updatedAt: nowIso() });
    repaired += 1;
  }

  // Workspaces created before the booking flow existed have an empty Bookings
  // tab. Give them the same demo diary a new workspace gets, once.
  let seeded: { bookings: number; campaign?: string } | undefined;
  const hasBookings = list<Doc>('bookings', (b) => (b as { orgId?: string }).orgId === orgId).length > 0;
  // Same rule as `seedOrg`: a workspace that asked for no invented history must not
  // get some on its second bootstrap call either. This path exists to repair
  // workspaces made *before* the booking flow shipped (see PRACTICE.md §11), which
  // is a demo-workspace problem, not a customer's.
  if (!hasBookings && demoHistoryEnabled()) {
    const assistants = list<Doc>('assistants', (a) => (a as { orgId?: string }).orgId === orgId);
    const numbers = list<Doc>('numbers', (n) => (n as { orgId?: string }).orgId === orgId);
    if (assistants.length && numbers.length) {
      seeded = await seedBookingsAndCampaign(orgId, assistants, numbers);
    }
  }

  return { toolsAdded: missing.length, assistantsRepaired: repaired, seededBookings: seeded?.bookings ?? 0, campaign: seeded?.campaign };
}


/**
 * The seeded workspace owner is verified.
 *
 * Verification now has teeth: publishing an assistant, buying a number and
 * minting an API key all refuse an unverified account (`requireVerifiedEmail`).
 * That is right for a real signup and wrong for the fixture the whole demo runs
 * on — `jordan@northwind.dev` is seeded with a known password, and the front desk
 * login beside it is already seeded verified for the same reason: a workspace
 * that cannot buy a number is not a working demo.
 *
 * So this is deliberate and narrow. It runs only for the demo owner, in the demo
 * workspace, and it audits itself, because "an account was verified without a
 * code" is exactly the kind of thing a records product should leave a trace of.
 */
export function ensureDemoOwnerVerified(orgId: string) {
  const demo = userByEmail('jordan@northwind.dev');
  if (!demo || demo.orgId !== orgId) return { verified: false as const, reason: 'not the demo workspace' };
  if (demo.emailVerified) return { verified: false as const, reason: 'already verified' };
  markEmailVerified(demo.id);
  audit({
    orgId,
    actor: 'system',
    action: 'auth.seed_verified',
    target: demo.id,
    detail: 'seeded workspace owner: the demo cannot be behind the verification gate',
  });
  return { verified: true as const, user: demo.id };
}

/**
 * The demo workspace gets a front desk.
 *
 * A records product has a rule that only means something if somebody can watch it
 * work (PRACTICE.md §11, P5): *a receptionist cannot open a note.* Proving that
 * needs a real second login with the real `receptionist` role — not a mock, and
 * not a second password for the owner. So the seeded Northwind workspace has one,
 * exactly as a clinic would: `desk@northwind.dev`, same demo password.
 *
 * Guarded on the demo owner's own account, so a real customer's workspace never
 * gets a second login it did not ask for.
 */
export async function ensureFrontDesk(orgId: string) {
  const demo = userByEmail('jordan@northwind.dev');
  if (!demo || demo.orgId !== orgId) return { created: false as const, reason: 'not the demo workspace' };
  const existing = userByEmail('desk@northwind.dev');
  if (existing) return { created: false as const, user: existing.id, reason: 'already there' };

  const user = insert<Doc>('users', {
    id: newId('usr_'),
    email: 'desk@northwind.dev',
    name: 'Front desk',
    passwordHash: await hashPassword('demo-password-2026'),
    orgId,
    role: 'receptionist',
    emailVerified: true,
    twoFactorEnabled: false,
    createdAt: nowIso(),
  } as never);
  return { created: true as const, user: user.id };
}

/**
 * The notes layer (P5), populated the way the rest of the demo is: through the
 * real modules, on records that really exist.
 *
 * The two most recent appointments that have already happened get their
 * write-up. One is signed by the practitioner who saw the patient; the other is
 * left exactly as the agent leaves it — a draft with the call attached and a
 * section still blank, waiting for a person. That is the state the Notes tab is
 * for, and an empty tab would leave the record-access rules looking theoretical.
 *
 * Idempotent (it does nothing once the workspace has a note) and safe for a new
 * workspace too: with no past appointments yet there is nothing to write up, and
 * the first signed note arrives when someone signs one.
 */
export async function seedDemoNotes(orgId: string): Promise<{ seeded: number }> {
  if (notesFor(orgId).length) return { seeded: 0 };
  const finished = bookingsFor(
    orgId,
    (b) => String(b.status) === 'completed' && Boolean((b as { clientId?: string }).clientId) && new Date(String(b.startsAt)).getTime() < Date.now()
  ).sort((a, b) => String(b.startsAt).localeCompare(String(a.startsAt)));
  if (!finished.length) return { seeded: 0 };

  let seeded = 0;
  // The practitioner who signs: whoever the visit was with, or the first name on
  // the practice's own roster when the appointment predates provider assignment.
  const provider =
    (finished[0].providerId ? providerById(orgId, String(finished[0].providerId)) : undefined) ?? providersFor(orgId)[0];
  const signerName = provider?.name ?? 'The practitioner';
  const signer = `${String(signerName).toLowerCase().replace(/[^a-z]+/g, '.')}@northwind.dev`;

  // --- one signed: the visit that happened, written up and closed -----------
  const first = finished[0];
  const opened = createNote({
    orgId,
    clientId: String((first as { clientId?: string }).clientId),
    bookingId: first.id,
    serviceId: first.serviceId ? String(first.serviceId) : undefined,
    providerId: (first.providerId ? String(first.providerId) : undefined) ?? provider?.id,
    actor: signer,
    actorName: signerName,
  });
  if (opened.ok) {
    const written: Record<string, string> = {
      presentation: 'Attended as booked, no change in symptoms reported since the last visit.',
      assessment: 'Everything checked is within expected limits; nothing new to investigate today.',
      treatment: 'The appointment went ahead as planned and was carried out without complication.',
      plan: 'No further visit needed unless something changes. Ring the practice if it does.',
      advice: 'Keep to the routine already agreed and keep the paperwork that came with the visit.',
      attended: 'Attended and completed the appointment that was booked for today.',
      work: 'The work was carried out in full, with nothing left part-done.',
      parts: 'Nothing beyond the usual materials was needed.',
      followup: 'No return visit is needed; the desk will ring if anything needs attention.',
      summary: 'Came in about the appointment that had been booked and it was dealt with in full.',
      detail: 'Discussed what was needed, agreed the way forward, and nothing was left outstanding.',
      next: 'Nothing outstanding — the practice will be in touch if anything changes.',
    };
    const filled = opened.note.sections.map((sec) => ({ ...sec, body: written[sec.id] ?? 'Recorded in full today.' }));
    const saved = updateNote({ orgId, id: opened.note.id, expectedRevision: opened.note.revision, patch: { sections: filled }, actor: signer, actorName: signerName });
    if (saved.ok) finaliseNote({ orgId, id: opened.note.id, expectedRevision: saved.note.revision, signerId: signer, signerName, actor: signer });
    seeded += 1;
  }

  // --- one unsigned, and it comes off a call -------------------------------
  //
  // The second write-up is not written by this seeder at all. The practice rings
  // the next patient to ask how the visit went — through the real runtime, the
  // same way the seeded call history is made — and when that call ends, the agent
  // leaves its draft on the appointment by itself (see `calls.ts`). The demo's
  // unsigned note is therefore the *product* behaving, not a fixture that looks
  // like it did.
  const second = finished.find((b) => b.id !== first.id);
  if (second) {
    const assistant = list<Doc & { name?: string }>('assistants', (a) => (a as { orgId?: string }).orgId === orgId).find((a) =>
      String(a.name ?? '').toLowerCase().includes('appointment')
    );
    const line = list<Doc & { number?: string }>('numbers', (n) => (n as { orgId?: string }).orgId === orgId)[0];
    const customer = second.customer as { name?: string; number?: string } | undefined;
    if (assistant && line?.number && customer?.number) {
      const when = new Date(new Date(String(second.startsAt)).getTime() + 3_600_000);
      const { call } = createCall({
        orgId,
        assistantId: String(assistant.id),
        type: 'outbound',
        from: String(line.number),
        to: customer.number,
        numberId: String(line.id),
        customer: { name: String(customer.name ?? 'Patient'), number: customer.number },
        source: 'seed-follow-up',
        bookingId: second.id,
      });
      if (call) {
        update<Doc>('calls', call.id, { startedAt: when.toISOString() });
        await appendTurn({
          orgId,
          callId: call.id,
          text: 'Hello, it is the practice here — just checking how the appointment went the other day.',
          offsetSeconds: 5,
        });
        endCall({ orgId, callId: call.id, endedAt: new Date(when.getTime() + 41_000).toISOString() });
        if (notesFor(orgId).some((n) => n.bookingId === second.id && n.draftedBy === 'agent')) seeded += 1;
      }
    }
  }

  return { seeded };
}

/**
 * The money layer (P6), populated the way the rest of the demo is: through the
 * real modules, against the appointments that actually happened.
 *
 * Six past visits become the practice's books — four paid in full, one paid in
 * part, one unpaid and now overdue — plus a credit note against one of them (a
 * visit that was charged at the wrong rate, corrected the way a records system
 * wants it corrected), a small set of expenses, and one open payment link on the
 * unpaid invoice so the desk can watch a sandbox payment settle it.
 *
 * Idempotent: it does nothing once the workspace has any invoice. Workspaces get
 * their payment types either way — that is the counter's vocabulary, not a demo.
 */
export function seedDemoMoney(orgId: string): { seeded: number; paymentTypes: number } {
  const paymentTypes = seedPaymentTypes(orgId).seeded;
  if (invoicesFor(orgId, { includeDrafts: true, includeVoid: true }).length) return { seeded: 0, paymentTypes };

  const finished = bookingsFor(
    orgId,
    (b) => String(b.status) === 'completed' && Boolean((b as { clientId?: string }).clientId) && new Date(String(b.startsAt)).getTime() < Date.now()
  ).sort((a, b) => String(b.startsAt).localeCompare(String(a.startsAt)));
  if (!finished.length) return { seeded: 0, paymentTypes };

  const settings = moneySettingsFor(orgId);
  const actor = 'seed';
  const actorName = 'Practice books (seed)';
  let seeded = 0;

  const visit = (index: number) => finished[index % finished.length];
  // Which practitioner the work is attributed to. A seeded appointment predates
  // provider assignment, so the roster supplies a name — revenue with no name on it
  // is a report nobody can act on.
  const roster = providersFor(orgId);
  const raise = (index: number, issueAfterDays: number) => {
    const booking = visit(index);
    const doneBy = booking.providerId ? String(booking.providerId) : roster[index % Math.max(1, roster.length)]?.id;
    const created = createInvoice({
      orgId,
      clientId: String((booking as { clientId?: string }).clientId),
      bookingIds: [booking.id],
      source: 'seed',
      actor,
      actorName,
      lines: [
        {
          description: `${booking.service ?? 'Appointment'} — ${String(booking.startsAt).slice(0, 10)}`,
          qty: 1,
          unitAmountMinor: toMinor(Number(booking.value ?? 120), settings.currency),
          taxRatePct: 0,
          bookingId: booking.id,
          providerId: doneBy,
        },
      ],
    });
    if (!created.ok) return undefined;
    const issueDate = new Date(Date.now() - issueAfterDays * 86_400_000).toISOString();
    const issued = issueInvoice({ orgId, id: created.value.id, issueDate, actor, actorName });
    return issued.ok ? issued.value : undefined;
  };

  // Four visits billed and settled.
  const paid = [0, 1, 2, 3].map((i) => raise(i, 21 - i * 3)).filter(Boolean);
  for (const invoice of paid) {
    recordPayment({
      orgId,
      clientId: invoice!.clientId,
      invoiceId: invoice!.id,
      kind: 'payment',
      method: i2m(paid.indexOf(invoice!)),
      amount: invoice!.totalMinor / 100,
      reference: invoice!.number,
      source: 'seed',
      actor,
      actorName,
      at: new Date(new Date(String(invoice!.issueDate)).getTime() + 86_400_000).toISOString(),
    });
    seeded += 1;
  }

  // One paid in part, still owing the rest.
  const part = raise(4, 12);
  if (part) {
    recordPayment({
      orgId,
      clientId: part.clientId,
      invoiceId: part.id,
      kind: 'payment',
      method: 'card',
      amount: part.totalMinor / 200,
      reference: `${part.number} (part payment)`,
      source: 'seed',
      actor,
      actorName,
      at: new Date(new Date(String(part.issueDate)).getTime() + 2 * 86_400_000).toISOString(),
    });
    seeded += 1;
  }

  // One billed, unpaid, and past its due date — the one the desk has to chase.
  const overdue = raise(5, 30);
  if (overdue) {
    seeded += 1;
    // A deposit taken before the visit, still sitting on the account.
    recordPayment({
      orgId,
      clientId: overdue.clientId,
      kind: 'prepayment',
      method: 'cash',
      amount: 25,
      reference: 'Deposit taken at the desk',
      note: 'Held on account against the next visit',
      source: 'seed',
      actor,
      actorName,
      at: new Date(new Date(String(overdue.issueDate)).getTime() - 86_400_000).toISOString(),
    });
  }

  // A credit note: one of the settled visits was billed at the wrong rate, and a
  // records system corrects that with a document rather than by editing history.
  if (paid[1]) {
    const credited = creditInvoice({
      orgId,
      id: paid[1]!.id,
      amountMinor: Math.max(1, Math.round(paid[1]!.totalMinor / 10)),
      reason: 'Overcharged on the day — corrected at the desk',
      actor,
      actorName,
    });
    if (credited.ok) seeded += 1;
  }

  // A month of the practice's costs, so the money screen has two sides.
  const spend: { category: string; supplier: string; description: string; amount: number; daysAgo: number }[] = [
    { category: 'rent', supplier: 'Bryant Street Properties', description: 'Monthly rent — consulting rooms', amount: 2400, daysAgo: 25 },
    { category: 'supplies', supplier: 'Northwind Medical Supplies', description: 'Consumables and paper stock', amount: 318.4, daysAgo: 18 },
    { category: 'software', supplier: 'Voxera', description: 'Phone assistant — monthly plan', amount: 149, daysAgo: 12 },
    { category: 'marketing', supplier: 'Local Health Directory', description: 'Directory listing', amount: 90, daysAgo: 9 },
    { category: 'utilities', supplier: 'City Power & Water', description: 'Utilities', amount: 214.75, daysAgo: 4 },
  ];
  for (const row of spend) {
    const created = createExpense({
      orgId,
      at: new Date(Date.now() - row.daysAgo * 86_400_000).toISOString().slice(0, 10),
      category: row.category,
      supplier: row.supplier,
      description: row.description,
      amount: row.amount,
      actor,
      actorName,
    });
    if (created.ok) seeded += 1;
  }

  return { seeded, paymentTypes };
}

/**
 * An open payment link on the unpaid invoice, so the sandbox flow can be watched
 * end to end from the dashboard. Separate from `seedDemoMoney` because it is
 * async (a Stripe workspace really does call Stripe here) and because a link is a
 * thing somebody sends, not a thing the books contain.
 */
export async function seedDemoPaymentLink(orgId: string, origin: string): Promise<{ created: boolean; url?: string }> {
  const open = invoicesFor(orgId, { includeDrafts: false }).filter((i) => i.kind === 'invoice' && ['issued', 'overdue', 'partly_paid'].includes(i.status) && i.totalMinor - i.paidMinor > 0);
  if (!open.length) return { created: false };
  const target = open[0];
  const existing = (await import('./payments')).linksFor(orgId, { invoiceId: target.id, status: 'open' });
  if (existing.length) return { created: false, url: existing[0].url };
  const created = await createPaymentLink({ orgId, invoiceId: target.id, origin, actor: 'seed', actorName: 'Practice books (seed)' });
  return created.ok ? { created: true, url: created.link.url } : { created: false };
}

function i2m(index: number): 'card' | 'cash' | 'bank_transfer' | 'voucher' {
  return (['card', 'cash', 'bank_transfer', 'card'] as const)[index % 4];
}

/**
 * Seeds the booking flow: a week of appointments, calls whose outcomes are
 * already known, and the campaign that rings about them.
 *
 * Used by a brand-new workspace and, idempotently, by `upgradeBookingTools` for
 * workspaces that existed before the booking flow did — a client opening the
 * dashboard for the first time should see the product working, not an empty tab.
 */
async function seedBookingsAndCampaign(
  orgId: string,
  assistants: Doc[],
  numbers: Doc[]
): Promise<{ bookings: number; campaign?: string }> {
  const rand = mulberry(orgId.length * 104729 + 7);
  // A week of appointments on the calendar, in the shape a client's own system
  // would push them, plus the campaign that rings about them. This is the flow
  // the product exists for, so a new workspace starts with it populated rather
  // than with an empty screen and a slogan.
  const SERVICES = ['Checkup', 'Consultation', 'Site visit', 'Installation', 'Follow-up', 'Estimate'];
  const SLOTS = [9, 10, 11, 14, 15, 16];
  const seededBookings: { id: string; externalId: string }[] = [];
  for (let i = 0; i < 24; i += 1) {
    const daysAhead = Math.floor(i / 4);
    const at = new Date();
    at.setDate(at.getDate() + daysAhead);
    at.setHours(SLOTS[i % SLOTS.length], i % 2 ? 30 : 0, 0, 0);
    const customerName = pickName(rand);
    const { booking } = upsertBooking({
      orgId,
      externalId: `NW-BK-${4100 + i}`,
      customer: { name: customerName, number: `+1 ${Math.floor(200 + rand() * 700)} 555 0${Math.floor(100 + rand() * 800)}`, email: `${customerName.split(' ')[0].toLowerCase()}@example.com` },
      service: SERVICES[i % SERVICES.length],
      startsAt: at.toISOString(),
      durationMinutes: 30,
      timezone: 'America/Los_Angeles',
      status: 'confirmed',
      value: Math.round(80 + rand() * 420),
      source: 'seed',
      metadata: { system: 'northwind-scheduler' },
    });
    seededBookings.push({ id: booking.id, externalId: booking.externalId });
  }

  // A handful of calls that already happened, so the dashboard shows outcomes
  // rather than only plans — and so the campaign has history on first load.
  const appointmentAssistant = assistants.find((a) => String(a.name).toLowerCase().includes('appointment')) ?? assistants[0];
  const OUTCOMES = ['confirmed', 'confirmed', 'confirmed', 'rescheduled', 'no_answer', 'cancelled'] as const;
  for (let i = 0; i < 6; i += 1) {
    const target = seededBookings[i * 2];
    const outcome = OUTCOMES[i];
    const when = new Date(Date.now() - (i + 1) * 3_600_000);
    const { call } = createCall({
      orgId,
      assistantId: String(appointmentAssistant.id),
      type: 'outbound',
      from: String(numbers[1].number),
      to: '+1 415 555 0150',
      numberId: String(numbers[1].id),
      customer: { name: pickName(rand), number: '+1 415 555 0150' },
      source: 'seed-campaign:confirm',
      bookingId: target.id,
    });
    if (call) {
      update<Doc>('calls', call.id, { startedAt: when.toISOString() });
      await appendTurn({ orgId, callId: call.id, text: 'Hi, this is Voxera calling about your appointment — are you still able to make it?' , offsetSeconds: 6 });
      endCall({ orgId, callId: call.id, endedAt: new Date(when.getTime() + 48_000).toISOString() });
      const { applyOutcome } = await import('./bookings');
      applyOutcome({
        orgId,
        bookingId: target.id,
        outcome,
        callId: call.id,
        note: outcome === 'rescheduled' ? 'caller asked for a later slot' : outcome === 'cancelled' ? 'caller cannot make it' : undefined,
      });
    }
  }

  const campaign = createCampaign({
    orgId,
    name: 'Tomorrow’s appointments — confirmation',
    kind: 'confirm',
    assistantId: String(appointmentAssistant.id),
    numberId: String(numbers[1].id),
    withinHours: 24,
    maxPerRun: 5,
    quietHours: { start: 9, end: 19, timezone: 'America/Los_Angeles' },
    pacingSeconds: 1,
    status: 'paused',
    instructions:
      'You are calling {{customer}} about their {{appointment}} with Northwind. Confirm they are still coming. If they cannot make it, offer to move it to another day this week or cancel it. Keep it under a minute.',
  });


  return { bookings: seededBookings.length, campaign: campaign.name };
}

/** Runs the scripted calls through the real runtime, spread across the last N days. */
/**
 * Should a brand-new workspace arrive full of fabricated history?
 *
 * The demo answer is yes: a dashboard with no calls in it does not show anybody
 * what the product does, so `seedOrg` runs 168 scripted calls through the real
 * agent runtime and lets the latency percentiles, intent mix and invoices compute
 * themselves from them.
 *
 * The production answer is the opposite: a paying practice signing in for the
 * first time should see its own empty diary, not another company's made-up calls
 * presented as activity. `VOXERA_SEED_DEMO=0` gives that — every workspace still
 * gets its tools, assistants, numbers, webhook and API key, so the product works
 * from the first minute, and nothing gets invented.
 */
/**
 * Whether a brand-new workspace arrives with the demo's made-up history.
 *
 * The flag existed, but it defaulted to *on*: anything that did not set it — a
 * production deployment following `.env.example`, a container with no env beyond
 * the secrets — gave every new customer three assistants and 168 fabricated calls
 * on day one. Being explicit in the wrong direction is worse than not having the
 * knob, so the default now depends on where the code is running: development gets
 * the demo because that is the point of it, production gets an empty diary unless
 * someone deliberately asks for the demo data.
 */
export function demoHistoryEnabled(): boolean {
  const flag = process.env.VOXERA_SEED_DEMO;
  if (flag === '1') return true;
  if (flag === '0') return false;
  return process.env.NODE_ENV !== 'production';
}

export async function seedOrg(orgId: string, origin: string, options: { history?: boolean } = {}) {
  if (
    count('assistants', (a) => (a as { orgId?: string }).orgId === orgId) > 0 ||
    count('tools', (tool) => (tool as { orgId?: string }).orgId === orgId) > 0
  ) {
    return { seeded: false, reason: 'org_not_empty' as const };
  }
  const withHistory = options.history ?? demoHistoryEnabled();

  insertMany<Doc>(
    'tools',
    TOOLS.map((t) => ({
      id: `tool_${newId('').slice(1, 9)}`,
      orgId,
      name: t.name,
      description: t.description,
      method: t.method,
      endpoint: t.endpoint,
      createdAt: nowIso(),
    })) as Doc[]
  );

  // Demo assistants are useful only in an explicitly demo workspace. A real
  // signup starts empty and creates a reviewed draft through guided setup.
  const assistants = withHistory
    ? insertMany<Doc>(
        'assistants',
        ASSISTANTS.map((a) => ({
          id: `asst_${newId('').slice(1, 11)}`,
          orgId,
          name: a.name,
          firstMessage: a.firstMessage,
          systemPrompt: a.systemPrompt,
          model: a.model,
          voiceId: a.voiceId,
          temperature: 0.4,
          transcriber: 'deepgram-nova-3',
          language: 'en-US',
          tools: a.tools,
          knowledge: a.knowledge,
          serverUrl: 'https://api.northwind.dev/voxera/hooks/calls',
          status: a.status,
          template: a.template,
          calls: 0,
          minutes: 0,
          containment: 0,
          createdAt: nowIso(),
          updatedAt: nowIso(),
          version: 1,
          source: 'demo',
        })) as Doc[]
      )
    : [];

  const numbers = withHistory
    ? insertMany<Doc>(
        'numbers',
        [
          { label: 'Support line', number: '+1 415 555 0142', areaCode: '415', assistantId: assistants[0].id, country: 'US' },
          { label: 'Appointments', number: '+1 415 555 0188', areaCode: '415', assistantId: assistants[1].id, country: 'US' },
        ].map((n) => ({
          id: `num_${newId('').slice(1, 9)}`,
          orgId,
          number: n.number,
          label: n.label,
          provider: 'twilio',
          assistantId: n.assistantId,
          country: n.country,
          areaCode: n.areaCode,
          status: 'active',
          monthlyCost: 1.15,
          inboundCalls30d: 0,
          createdAt: nowIso(),
          source: 'demo',
        })) as Doc[]
      )
    : [];

  // A webhook subscription that points back at this deployment, so deliveries in
  // the dashboard are observable rather than theoretical.
  const sub: WebhookSubscription | undefined = withHistory
    ? ({
        id: newId('wh_'),
        orgId,
        url: `${origin}/api/webhook-echo`,
        events: ['call.ended', 'assistant.updated'],
        secretSealed: sealWebhookSecret(newId('whsec_')),
        active: true,
        createdAt: nowIso(),
      } as WebhookSubscription)
    : undefined;
  if (sub) insert<WebhookSubscription>('webhooks', sub);

  // ---------------------------------------------------------------- call history
  const published = assistants.filter((a) => a.status === 'published');
  const rand = mulberry(orgId.length * 7919);
  const DAYS = 14;
  const HISTORY = withHistory ? 168 : 0;
  let placed = 0;

  for (let i = 0; i < HISTORY; i += 1) {
    const assistant = published[i % published.length];
    const script = CALLER_LINES[Math.floor(rand() * CALLER_LINES.length)].filter(Boolean);
    // Extend short scripts so calls read like conversations rather than one-liners.
    const lines = script.concat(FILLER.slice(0, Math.max(0, 4 + Math.floor(rand() * 7) - script.length)));

    // Business-hours weighted start time, `daysAgo` days back.
    const daysAgo = Math.floor((i / HISTORY) * DAYS);
    const hour = 8 + Math.floor(rand() * 11);
    const start = new Date(Date.now() - daysAgo * 86400000);
    start.setHours(hour, Math.floor(rand() * 60), Math.floor(rand() * 60), 0);

    const number = numbers.find((n) => n.assistantId === assistant.id);
    const { call } = createCall({
      orgId,
      assistantId: String(assistant.id),
      type: rand() > 0.74 ? 'outbound' : rand() > 0.5 ? 'web' : 'inbound',
      from: `+1 ${Math.floor(200 + rand() * 700)} 555 0${Math.floor(100 + rand() * 800)}`,
      to: String(number?.number ?? '+1 415 555 0100'),
      numberId: number ? String(number.id) : undefined,
      customer: {
        name: pickName(rand),
        number: `+1 ${Math.floor(200 + rand() * 700)} 555 0${Math.floor(100 + rand() * 800)}`,
        company: rand() > 0.72 ? pickCompany(rand) : undefined,
      },
      // Marked as seeded on purpose: onboarding counts *your* calls, and a demo
      // call must never be mistaken for one.
      source: rand() > 0.86 ? 'seed-api' : 'simulation',
    });
    if (!call) continue;

    update<Doc>('calls', call.id, { startedAt: start.toISOString() });
    Object.assign(call, { startedAt: start.toISOString() });

    // Each exchange takes 9–24s of speech plus think time; the call ends ~12s
    // after the last thing the caller says.
    let offset = 4;
    for (const line of lines) {
      offset += 9 + Math.floor(rand() * 15);
      await appendTurn({ orgId, callId: call.id, text: line, offsetSeconds: offset });
    }
    const ended = new Date(start.getTime() + (offset + 12) * 1000);
    endCall({ orgId, callId: call.id, endedAt: ended.toISOString() });
    placed += 1;
  }

  // The in-flight call the dashboard can pick up mid-conversation.
  const liveNumber = numbers[0];
  const live = withHistory ? createCall({
    orgId,
    assistantId: String(published[0].id),
    type: 'inbound',
    from: '+1 415 555 0177',
    to: String(liveNumber.number),
    numberId: String(liveNumber.id),
    customer: { name: 'Amara Osei', number: '+1 415 555 0177', company: 'Kavak' },
    source: 'seed-phone',
  }) : { call: null };
  if (live.call) {
    await appendTurn({ orgId, callId: live.call.id, text: 'Hi — my invoice has the wrong billing address on it.' });
  }

  /**
   * The demo diary: appointments, a campaign, a month of visits.
   *
   * Part of the demo, not part of a workspace — a real practice entering its own
   * patients does not want another practice's invented ones sitting in its
   * calendar. `VOXERA_SEED_DEMO=0` keeps the structure (assistants, numbers,
   * services, rotas, templates) and skips the fiction.
   */
  const bookingSeed = withHistory
    ? await seedBookingsAndCampaign(orgId, assistants, numbers)
    : { bookings: 0, campaign: null };

  // Number-level counters reflect the calls that were actually logged.
  const endedCalls = listAllByOrg<Doc & { numberId?: string }>('calls', orgId);
  numbers.forEach((n) => {
    const count_ = endedCalls.filter((c) => c.numberId === n.id).length;
    update<Doc>('numbers', String(n.id), { inboundCalls30d: count_, lastCallAt: nowIso() });
  });

  const apiKey = withHistory ? createApiKey(orgId, 'Default key', 'system', ['*']) : undefined;
  if (withHistory) {
    insert<Doc>('providerSettings', {
      id: `ps_${newId('').slice(1, 9)}`,
      orgId,
      mode: 'managed',
      llm: 'openai',
      stt: 'deepgram',
      tts: 'cartesia',
      telephony: 'twilio',
      updatedAt: nowIso(),
    } as Doc);
  }

  // Demo workspaces get a watchable diary. A real workspace must enter its own
  // sites, services, team and rota; invented people or prices would be unsafe.
  const practice = withHistory ? seedPractice(orgId) : { seeded: false, reason: 'setup_required' };
  // And the wording it will use when it does: templates in the workspace's own
  // vocabulary. Not inside `seedPractice`, because that module must not import
  // the template module that imports it.
  const templates = seedTemplatesForOrg(orgId);

  return {
    seeded: true,
    templates,
    assistants: assistants.length,
    calls: placed,
    numbers: numbers.length,
    bookings: bookingSeed.bookings,
    campaign: bookingSeed.campaign,
    practice,
    attribution: attributeSeededDiary(orgId),
    apiKey: apiKey ? { id: apiKey.key.id, name: apiKey.key.name, secret: apiKey.plaintext } : undefined,
    webhookUrl: sub?.url,
  };
}

/**
 * Puts the seeded diary on the workspace's own services and practitioners.
 *
 * The demo's appointments were written before the practice layer existed: they
 * name a job ("Checkup", "Site visit") in a string and nothing else. Reports can
 * only say *who earned what* if the rows say who did it, and an owner's screen
 * that opens on a huge "Unassigned" bar is worse than no screen — so this is the
 * one-time migration every real practice performs when it moves a diary in:
 * match each appointment to a service that exists, and to a practitioner who
 * offers it.
 *
 * Deliberately narrow:
 *  - only seeded appointments (`source === 'seed'`) with no `serviceId` are touched;
 *  - a service is only ever created for a job type the diary actually contains;
 *  - the same appointment and invoice are never rewritten twice (idempotent by
 *    the same condition that finds them);
 *  - nothing is deleted, and an appointment that already names a practitioner is
 *    left exactly as it is.
 */
export function attributeSeededDiary(orgId: string): { services: number; appointments: number; lines: number; rostered: number } {
  const seeded = bookingsFor(orgId, (b) => String((b as { source?: string }).source ?? '') === 'seed');
  const orphans = seeded.filter((b) => !(b as { providerId?: string }).providerId || !(b as { serviceId?: string }).serviceId);
  if (!orphans.length) return { services: 0, appointments: 0, lines: 0, rostered: 0 };

  const known = new Map(servicesFor(orgId, { includeInactive: true }).map((s) => [s.name.trim().toLowerCase(), s]));
  let created = 0;
  const serviceFor = (booking: BookingDoc) => {
    const name = String((booking as { service?: string }).service ?? 'Appointment').trim();
    const existing = known.get(name.toLowerCase());
    if (existing) return existing;
    // A job type the diary books but the service list never learned about. Priced
    // from the booking's own value where there is one, so the money stays truthful.
    const row = createService(
      orgId,
      { name, durationMinutes: Number((booking as { durationMinutes?: number }).durationMinutes ?? 30), price: Number((booking as { value?: number }).value ?? 0) },
      'seed'
    );
    known.set(name.toLowerCase(), row);
    created += 1;
    return row;
  };

  const roster = providersFor(orgId);
  const providerFor = (booking: BookingDoc, serviceId: string) => {
    const current = String((booking as { providerId?: string }).providerId ?? '');
    if (current) return current;
    const offered = roster.filter((p) => p.serviceIds?.includes(serviceId));
    const pool = offered.length ? offered : roster;
    if (!pool.length) return undefined;
    // Rotate on a stable hash of the appointment so the same row always lands on
    // the same person, however many times this runs.
    const seed = String((booking as { externalId?: string }).externalId ?? (booking as { id?: string }).id ?? '');
    let hash = 0;
    for (let i = 0; i < seed.length; i += 1) hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
    return pool[hash % pool.length].id;
  };

  let appointments = 0;
  const fixedByBooking = new Map<string, { serviceId: string; providerId?: string }>();
  // Who offers a service we just learned about: the people who did that job. A
  // service nobody is rostered for is a service the booking page would offer and
  // then refuse, so the roster is updated with the same sentence that created it.
  const offeredBy = new Map<string, Set<string>>();
  for (const booking of orphans) {
    const service = serviceFor(booking);
    const providerId = providerFor(booking, service.id);
    update<Doc>('bookings', booking.id, { serviceId: service.id, providerId } as never);
    fixedByBooking.set(booking.id, { serviceId: service.id, providerId });
    if (providerId) {
      const set = offeredBy.get(service.id) ?? new Set<string>();
      set.add(providerId);
      offeredBy.set(service.id, set);
    }
    appointments += 1;
  }

  let rostered = 0;
  for (const [serviceId, providerIds] of offeredBy) {
    for (const providerId of providerIds) {
      const provider = providerById(orgId, providerId);
      const current = provider?.serviceIds ?? [];
      if (!provider || current.includes(serviceId)) continue;
      update<Doc>('providers', providerId, { serviceIds: [...current, serviceId] } as never);
      rostered += 1;
    }
  }

  // The invoices raised from those appointments: a line with no service or
  // practitioner cannot be attributed to either, so it is filled in from the
  // appointment it was billed for.
  let lines = 0;
  for (const invoice of invoicesFor(orgId, { includeDrafts: true, includeVoid: true })) {
    const bookingId = (invoice.bookingIds ?? []).map(String).find((id) => fixedByBooking.has(id));
    if (!bookingId) continue;
    const fix = fixedByBooking.get(bookingId)!;
    let changed = false;
    const next = invoice.lines.map((line) => {
      if (line.serviceId && line.providerId) return line;
      changed = true;
      lines += 1;
      return { ...line, serviceId: line.serviceId ?? fix.serviceId, providerId: line.providerId ?? fix.providerId };
    });
    if (changed) update<Doc>('invoices', invoice.id, { lines: next } as never);
  }

  return { services: created, appointments, lines, rostered };
}

const FILLER = [
  'Yes, that makes sense.',
  'Could you repeat that part?',
  'Okay, and how long does that normally take?',
  'Right — is there anything I need to do on my end?',
  'That sounds good to me.',
  'Can you text me the details as well?',
  'One more thing, is that covered under warranty?',
  'Understood. Thanks for checking.',
  'Sorry, I did not catch the last bit.',
  'And if it does not arrive, who do I contact?',
  'Perfect, that is everything.',
];

/* ---------------------------------------------------------------- utilities */

function mulberry(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const FIRST = ['Amara', 'Devin', 'Priya', 'Marcus', 'Lena', 'Tomas', 'Nadia', 'Owen', 'Sofia', 'Ravi', 'Iris', 'Jonah'];
const LAST = ['Osei', 'Park', 'Raghavan', 'Ellery', 'Ford', 'Eriksen', 'Haddad', 'Brooks', 'Duarte', 'Menon', 'Nakamura', 'Weiss'];
const COMPANIES = ['Kavak', 'Instawork', 'GoHealth', 'Meridian Freight', 'Brightline Care', 'Northgate Realty'];

function pickName(rand: () => number) {
  return `${FIRST[Math.floor(rand() * FIRST.length)]} ${LAST[Math.floor(rand() * LAST.length)]}`;
}
function pickCompany(rand: () => number) {
  return COMPANIES[Math.floor(rand() * COMPANIES.length)];
}

